import SwiftUI

struct AppGuideView:View {
    @Environment(\.dismiss) private var dismiss
    @State private var query=""
    private var topics:[GuideTopic]{GuideCatalogue.topics(services:NetworkPolicy.enabled).filter{$0.matches(query)}}
    var body:some View{NavigationStack{ZStack{Ambient();ScrollView{VStack(alignment:.leading,spacing:20){SurfaceHeader(title:"دليل كوكيز",subtitle:"تعرف على مسار العمل، ثم اختر الأداة التي تحتاجها",icon:"book.closed");SearchBar(placeholder:"ابحث عن أداة أو ميزة",text:$query).accessibilityIdentifier("guide-search");if query.isEmpty{VStack(alignment:.leading,spacing:12){QuietBadge(text:"ابدأ هنا",icon:"sparkles");Text("من فصل خام إلى حوار جاهز.").font(.system(size:21,weight:.semibold));Text("خطوات واضحة، وملاحظات عملية لكل واجهة وأداة. اختر موضوعًا لقراءة الشرح الكامل.").font(.system(size:12)).foregroundStyle(Palette.secondary).lineSpacing(5)}.padding(22).glass(24)};ForEach(topics){topic in NavigationLink{GuideTopicView(topic:topic)}label:{HStack(spacing:14){SurfaceSymbol(icon:topic.icon,size:42);VStack(alignment:.leading,spacing:6){Text(topic.title).font(.system(size:15,weight:.semibold));Text(topic.subtitle).font(.system(size:11)).foregroundStyle(Palette.secondary).lineLimit(2)};Spacer(minLength:4);Image(systemName:"chevron.left").font(.system(size:11)).foregroundStyle(Palette.quiet)}.padding(18).glass(20)}.buttonStyle(.plain).accessibilityIdentifier("guide-topic-"+topic.id)};if topics.isEmpty{WorkspaceEmpty(title:"لا توجد نتائج",detail:"ابحث مثلًا عن التايبر، القطارة، الحدود، أو النسخ الاحتياطي.",icon:"magnifyingglass")}}.padding(20).frame(maxWidth:800).frame(maxWidth:.infinity)}.accessibilityIdentifier("guide-list")}.foregroundStyle(Palette.pale).navigationTitle("دليل التطبيق").navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.topBarLeading){Button("تم"){dismiss()}.accessibilityIdentifier("guide-close")}}}.cookiesInterface()}
}
private struct GuideTopicView:View {
    let topic:GuideTopic
    var body:some View{ZStack{Ambient();ScrollView{VStack(alignment:.leading,spacing:18){SurfaceHeader(title:topic.title,subtitle:topic.subtitle,icon:topic.icon);ForEach(Array(topic.entries.enumerated()),id:\.element.id){index,entry in VStack(alignment:.leading,spacing:14){HStack(alignment:.center,spacing:12){Text(String(format:"%02d",index+1)).font(.system(size:11,weight:.medium,design:.monospaced)).foregroundStyle(Palette.gold).frame(width:30,height:30).background(Palette.gold.opacity(0.07),in:RoundedRectangle(cornerRadius:9));Text(entry.title).font(.system(size:16,weight:.semibold));Spacer(minLength:0)};Text(entry.text).font(.system(size:14)).foregroundStyle(Palette.secondary).lineSpacing(7).textSelection(.enabled).fixedSize(horizontal:false,vertical:true)}.padding(20).glass(22)}}.padding(20).frame(maxWidth:800).frame(maxWidth:.infinity)}}.foregroundStyle(Palette.pale).navigationTitle(topic.title).navigationBarTitleDisplayMode(.inline).accessibilityIdentifier("guide-detail-"+topic.id)}
}
